/** End-to-end snapshot consistency while the startup adjacency build races transactional reads and writes. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbAdjacencyStartupConcurrencyTest {

	private static final String EX = "urn:adjacency-startup:";
	private static final int MEMBERS = 8;
	private static final int EPOCHS = 80;
	private static final int QUERY_PASSES = 100;

	private static final String CONSISTENCY_QUERY = """
			PREFIX ex: <urn:adjacency-startup:>
			SELECT ?epoch ?expected (COUNT(DISTINCT ?item) AS ?actual)
			WHERE {
			  ex:control ex:current ?epoch .
			  ?epoch ex:expected ?expected .
			  { ?epoch ex:member ?item }
			  UNION
			  { GRAPH ex:graph { ?epoch ex:member ?item } }
			  OPTIONAL { ?item ex:label ?label }
			  FILTER EXISTS { ?item ex:next ?tail }
			  FILTER NOT EXISTS { ?item ex:banned true }
			  MINUS { ?item ex:removed true }
			}
			GROUP BY ?epoch ?expected
			""";

	private static final String PATH_QUERY = """
			PREFIX ex: <urn:adjacency-startup:>
			ASK {
			  ex:control ex:current ?epoch .
			  ?epoch ex:member/ex:next ?tail .
			  ?item ^ex:member ?epoch .
			}
			""";

	@Test
	@Timeout(120)
	void queriesRemainSnapshotConsistentWhileStartupBuildCatchesContinuousTransactions(@TempDir File dataDir)
			throws Exception {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyBuildOnStart(false)
				.setDirectAdjacencyMaxBytes(1L << 30);
		LmdbStore sail = new LmdbStore(dataDir, config);
		SailRepository repository = new SailRepository(sail);
		repository.init();
		try (ExecutorService workers = Executors.newFixedThreadPool(3)) {
			writeEpoch(repository, 0, false);
			LmdbDirectAdjacencyStore adjacency = sail.getBackingStore().directAdjacencyStore();
			assertThat(adjacency).isNotNull();

			CountDownLatch scanComplete = new CountDownLatch(1);
			CountDownLatch releaseScan = new CountDownLatch(1);
			adjacency.afterBuildScanForTest = () -> {
				adjacency.afterBuildScanForTest = null;
				scanComplete.countDown();
				try {
					releaseScan.await();
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new AssertionError(e);
				}
			};
			adjacency.triggerBuild();
			assertThat(scanComplete.await(30, TimeUnit.SECONDS)).isTrue();

			long buildingFallbacks = adjacency.snapshotMetrics().fallbacks(FallbackReason.BUILDING);
			assertConsistentSnapshot(repository);
			assertThat(adjacency.snapshotMetrics().fallbacks(FallbackReason.BUILDING))
					.isGreaterThan(buildingFallbacks);

			AtomicBoolean stopReaders = new AtomicBoolean();
			AtomicInteger queryPasses = new AtomicInteger();
			AtomicInteger committedEpoch = new AtomicInteger();
			AtomicReference<Throwable> failure = new AtomicReference<>();
			CountDownLatch cutoverBacklogReady = new CountDownLatch(1);
			CountDownLatch resumePostCutoverWrites = new CountDownLatch(1);
			CompletableFuture<Void> readerOne = reader(repository, stopReaders, queryPasses, failure, workers);
			CompletableFuture<Void> readerTwo = reader(repository, stopReaders, queryPasses, failure, workers);
			long readerDeadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(30);
			while (queryPasses.get() < 10 && failure.get() == null) {
				if (System.nanoTime() >= readerDeadline) {
					throw new AssertionError("query workers did not complete the pre-cutover consistency quota");
				}
				Thread.onSpinWait();
			}
			int preCutoverQueryPasses = queryPasses.get();
			CompletableFuture<Void> writer = CompletableFuture.runAsync(() -> {
				try {
					for (int epoch = 1; epoch <= EPOCHS; epoch++) {
						writeEpoch(repository, epoch, epoch % 11 == 0);
						committedEpoch.set(epoch);
						if (epoch == 20) {
							cutoverBacklogReady.countDown();
							releaseScan.countDown();
							resumePostCutoverWrites.await();
						}
					}
				} catch (Throwable thrown) {
					failure.compareAndSet(null, thrown);
				} finally {
					releaseScan.countDown();
				}
			}, workers);

			try {
				assertThat(cutoverBacklogReady.await(30, TimeUnit.SECONDS))
						.as("writer failed before preparing the cutover backlog: %s", failure.get())
						.isTrue();
				boolean ready = sail.awaitDirectAdjacencyReady(30, TimeUnit.SECONDS);
				assertThat(ready).as(sail.getDirectAdjacencyReadinessDescription()).isTrue();
				assertConsistentSnapshot(repository);
				assertThat(adjacency.synchronousUpdatesActivatedForTest()).isTrue();
				assertThat(adjacency.lastCutoverRevisions()).isNotNegative();
				assertThat(adjacency.lastCutoverQueuedCommits()).isPositive();
				assertThat(adjacency.lastCutoverNanos()).isPositive();
				assertThat(adjacency.publishedStateForTest().appliedRevision())
						.isEqualTo(adjacency.snapshotMetrics().currentDataRevision);
			} finally {
				resumePostCutoverWrites.countDown();
			}
			try {
				writer.get(90, TimeUnit.SECONDS);
				assertConsistentSnapshot(repository);
			} finally {
				stopReaders.set(true);
				releaseScan.countDown();
				resumePostCutoverWrites.countDown();
			}
			readerOne.get(30, TimeUnit.SECONDS);
			readerTwo.get(30, TimeUnit.SECONDS);

			assertThat(failure.get()).isNull();
			assertThat(committedEpoch.get()).isEqualTo(EPOCHS);
			assertThat(queryPasses.get()).isGreaterThan(preCutoverQueryPasses);
			assertThat(adjacency.snapshotMetrics().lookupHits + adjacency.snapshotMetrics().exactMisses)
					.as("at least one covered post-readiness lookup must engage adjacency")
					.isPositive();
		} finally {
			repository.shutDown();
		}
	}

	private static CompletableFuture<Void> reader(SailRepository repository, AtomicBoolean stop,
			AtomicInteger queryPasses, AtomicReference<Throwable> failure, ExecutorService workers) {
		return CompletableFuture.runAsync(() -> {
			try (SailRepositoryConnection connection = repository.getConnection()) {
				while (!stop.get() && failure.get() == null && queryPasses.get() < QUERY_PASSES) {
					assertConsistentSnapshot(connection);
					assertThat(connection.prepareBooleanQuery(PATH_QUERY).evaluate()).isTrue();
					queryPasses.incrementAndGet();
				}
			} catch (Throwable thrown) {
				failure.compareAndSet(null, thrown);
			}
		}, workers);
	}

	private static void assertConsistentSnapshot(SailRepository repository) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			assertConsistentSnapshot(connection);
		}
	}

	private static void assertConsistentSnapshot(SailRepositoryConnection connection) {
		List<BindingSet> rows = QueryResults.asList(connection.prepareTupleQuery(CONSISTENCY_QUERY).evaluate());
		assertThat(rows).hasSize(1);
		Literal expected = (Literal) rows.get(0).getValue("expected");
		Literal actual = (Literal) rows.get(0).getValue("actual");
		assertThat(actual.intValue()).isEqualTo(expected.intValue()).isEqualTo(MEMBERS);
	}

	private static void writeEpoch(SailRepository repository, int epoch, boolean exerciseRollback) {
		try (SailRepositoryConnection connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI control = vf.createIRI(EX, "control");
			IRI current = vf.createIRI(EX, "current");
			IRI epochIri = vf.createIRI(EX, "epoch-" + epoch);
			if (exerciseRollback) {
				connection.begin();
				connection.remove(control, current, null);
				connection.add(control, current, vf.createIRI(EX, "rolled-back-" + epoch));
				connection.rollback();
			}

			connection.begin();
			connection.remove(control, current, null);
			connection.add(control, current, epochIri);
			connection.add(epochIri, vf.createIRI(EX, "expected"), vf.createLiteral(MEMBERS));
			for (int member = 0; member < MEMBERS; member++) {
				IRI item = vf.createIRI(EX, "item-" + epoch + '-' + member);
				IRI memberPredicate = vf.createIRI(EX, "member");
				if ((member & 1) == 0) {
					connection.add(epochIri, memberPredicate, item);
				} else {
					connection.add(epochIri, memberPredicate, item, vf.createIRI(EX, "graph"));
				}
				connection.add(item, vf.createIRI(EX, "next"), vf.createIRI(EX, "tail-" + member));
				if (member % 3 == 0) {
					connection.add(item, vf.createIRI(EX, "label"), vf.createLiteral("member " + member));
				}
			}
			connection.commit();
		}
	}
}
